-- reputation rewards on WoW Forever (Wowhead's WoW Forever faction pages): added to the Classic lists - Wowhead lists only
-- the items it ties to a reputation, so nothing is taken away - and a page for each faction Forever added
D.confirmed = D.confirmed or {}
local function Merge(page, standing, kind, f, list)
	for x = 1, #list, 2 do D.confirmed[list[x]] = true end
	local g
	for _, x in ipairs(page[3]) do if x[1] == standing and (x[3] or 0) == f then g = x end end
	if not g then g = { standing, kind, f, {} }; page[3][#page[3] + 1] = g end
	local have = {}
	for x = 1, #g[4], 2 do have[g[4][x]] = true end
	for x = 1, #list, 2 do if not have[list[x]] then g[4][#g[4] + 1] = list[x]; g[4][#g[4] + 1] = list[x + 1] end end
end
